import { RayBody, RayLight } from "type";
import { GameScene } from "../GameScene";

const debug = true;

export class Raycaster {
  constructor(scene: GameScene, light: RayLight, bodies: RayBody[]) {
    const shadows = bodies.map(
      ({ x, y, height, width, radius = 0, type = "circle" }) => {
        if (type === "circle") {
          const shadow = scene.add.circle(x, y, width / 2, 0x000000, 0.5);
          shadow.setScale(width / shadow.width, height / shadow.height);

          return shadow;
        } else {
        }
      },
    );
    if (debug) {
      const lightEdge = scene.add
        .circle(light.x, light.y, light.radius, 0xff0000)
        .setDepth(Infinity)
        .setAlpha(0.075);
    }
  }
}
